// Mirror the COMMITTED spawnStep logic exactly (chain.steps[i-1].agent — the NAME).
function chainContext(i, steps, name) {
  const prev = i > 0 ? steps[i-1].agent : undefined;     // .agent = name string
  const next = i+1 < steps.length ? steps[i+1].agent : undefined;
  return `[Chain context — your role in this run]\nYou are step ${i+1} of ${steps.length} in chain "${name}".\nPrevious agent: ${prev ?? "none — you are the first step"}.\nNext agent: ${next ?? "none — you are the final step"}.`;
}
function buildBody(systemPrompt, chainContext) {
  let body = systemPrompt;
  if (chainContext) body = body.trim() ? body + "\n\n" + chainContext : chainContext;
  return body;
}
let pass=0, fail=0; const c=(n,x)=>{x?pass++:fail++;console.log(`${x?"PASS":"FAIL"} ${n}`);};

const steps2 = [{agent:"scout"},{agent:"synthesizer"}];
const cc1 = chainContext(0, steps2, "inline");
console.log("--- step 1/2 ---\n"+cc1+"\n");
c("step1: step 1 of 2", cc1.includes("step 1 of 2"));
c("step1: prev = none (first)", cc1.includes("Previous agent: none — you are the first step"));
c("step1: next = synthesizer", cc1.includes("Next agent: synthesizer"));

const cc2 = chainContext(1, steps2, "inline");
console.log("--- step 2/2 ---\n"+cc2+"\n");
c("step2: step 2 of 2", cc2.includes("step 2 of 2"));
c("step2: prev = scout", cc2.includes("Previous agent: scout"));
c("step2: next = none (final)", cc2.includes("Next agent: none — you are the final step"));

const steps3 = [{agent:"planner"},{agent:"worker"},{agent:"reviewer"}];
const ccm = chainContext(1, steps3, "pipeline");
console.log("--- step 2/3 (middle) ---\n"+ccm+"\n");
c("mid: prev = planner", ccm.includes("Previous agent: planner"));
c("mid: next = reviewer", ccm.includes("Next agent: reviewer"));

const b1 = buildBody("You are a scout. Recon only.", cc1);
c("body: agent prompt first", b1.startsWith("You are a scout. Recon only."));
c("body: context after blank", b1.includes("You are a scout. Recon only.\n\n[Chain context"));
const b2 = buildBody("  ", cc2);
c("body: context-only when empty agent prompt", b2 === cc2);
const b3 = buildBody("You are a scout.", undefined);
c("body: agent-only when no chain ctx", b3 === "You are a scout.");

console.log(`\nresult: ${pass}/${pass+fail} passed ${fail===0?"✓":"✗"}`);
