import * as fs from "node:fs";
import * as path from "node:path";
import * as A from "./agents.ts";

// ── replicate the tool's EXACT frontmatter construction ──
function buildBody(name, description, systemPrompt, opts) {
  const fm = [`name: ${name}`, `description: ${description}`];
  if (opts.tools?.length) fm.push(`tools: ${opts.tools.join(", ")}`);
  if (opts.disallowedTools?.length) fm.push(`disallowedTools: ${opts.disallowedTools.join(", ")}`);
  if (opts.model) fm.push(`model: ${opts.model}`);
  if (opts.extensions?.length) fm.push(`extensions: ${opts.extensions.join(", ")}`);
  if (opts.skills?.length) fm.push(`skills: ${opts.skills.join(", ")}`);
  if (opts.worktree) fm.push(`worktree: true`);
  return `---\n${fm.join("\n")}\n---\n${systemPrompt.replace(/\n$/, "")}\n`;
}

const agentDir = path.join(A.getAgentDirSafe?.() ?? path.join(process.env.HOME, ".pi", "agent"), "agents");
const tmpFile = path.join(agentDir, "zbuildtest.md");

// case 1: full overlay (all fields)
const body1 = buildBody("zbuildtest", "Test agent full overlay.", "You are a test scout. Recon only.\nDo edits never.", {
  tools: ["read","grep","ls"], disallowedTools: ["edit","write"], model: "neuralwatt/glm-5.2-short",
  extensions: ["npm:pi-neuralwatt-provider"], skills: ["~/.pi/agent/skills/grilling"], worktree: true,
});
fs.writeFileSync(tmpFile, body1, { mode: 0o600 });

// run the REAL discoverAgents (same path subagent_catalog uses)
const found = A.discoverAgents(process.cwd(), "user").agents.find(a => a.name === "zbuildtest");
let pass = 0, fail = 0;
const c = (n, x) => { x ? pass++ : fail++; console.log(`${x?"PASS":"FAIL"} ${n}`); };

console.log("\n--- case 1: full overlay ---");
console.log(JSON.stringify(found, null, 2)?.slice(0, 500));
c("discovered", !!found);
c("name round-trips", found?.name === "zbuildtest");
c("description round-trips", found?.description === "Test agent full overlay.");
c("systemPrompt (body) round-trips w/ formatting", found?.systemPrompt === "You are a test scout. Recon only.\nDo edits never.");
c("tools list parses", JSON.stringify(found?.tools) === JSON.stringify(["read","grep","ls"]));
c("disallowedTools list parses", JSON.stringify(found?.disallowedTools) === JSON.stringify(["edit","write"]));
c("model round-trips", found?.model === "neuralwatt/glm-5.2-short");
c("extensions list parses", JSON.stringify(found?.extensions) === JSON.stringify(["npm:pi-neuralwatt-provider"]));
c("skills list parses", JSON.stringify(found?.skills) === JSON.stringify(["~/.pi/agent/skills/grilling"]));
c("worktree bool=true", found?.worktree === true);
c("source=user", found?.source === "user");

// case 2: minimal (only required fields)
const body2 = buildBody("zbuildtest", "Minimal.", "Be terse.", {});
fs.writeFileSync(tmpFile, body2, { mode: 0o600 });
const found2 = A.discoverAgents(process.cwd(), "user").agents.find(a => a.name === "zbuildtest");
console.log("\n--- case 2: minimal ---");
c("minimal discovered", !!found2);
c("minimal: tools undefined (not emitted)", found2?.tools === undefined);
c("minimal: worktree false (not emitted)", found2?.worktree === false);
c("minimal: body round-trips", found2?.systemPrompt === "Be terse.");

// case 3: multi-line systemPrompt (the interesting body case)
const body3 = buildBody("zbuildtest", "Multi-line body.", "You are X.\n\n## Rules\n- rule 1\n- rule 2", {});
fs.writeFileSync(tmpFile, body3, { mode: 0o600 });
const found3 = A.discoverAgents(process.cwd(), "user").agents.find(a => a.name === "zbuildtest");
c("multiline body preserves blank line + bullets", found3?.systemPrompt === "You are X.\n\n## Rules\n- rule 1\n- rule 2");

// ── validation cases (name pattern) ──
console.log("\n--- validation ---");
const valid = /^[a-z0-9][a-z0-9-]*$/;
for (const [n, exp] of [["scout",true],["api-reviewer",true],["a",true],["Scout",false],["api_reviewer",false],["api reviewer",false],["1test",true],["-lead",false],["UPPER",false]]) {
  c(`name "${n}" ${exp?"valid":"rejected"}`, valid.test(n) === exp);
}

fs.unlinkSync(tmpFile);
console.log(`\nresult: ${pass}/${pass+fail} passed ${fail===0?"✓":"✗"}`);
EOF
