input {"args":["eval","--stdin"],"stdin":"// 1. Charts stacked (one per row, full width): .trends grid should be single column
// 2. Provider titles are links to the analytics URLs
const trendGrid = document.querySelector('div[class*="trends"]');
const trendCards = document.querySelectorAll('section[aria-label$=" trend"]');
const gridStyle = trendGrid ? getComputedStyle(trendGrid) : null;
const providerLinks = [...document.querySelectorAll('a')].filter(a =>
 a.href.includes('chatgpt.com/codex/cloud/settings/analytics') ||
 a.href.includes('portal.neuralwatt.com/dashboard/usage')
);
JSON.stringify({
 // Change 1: charts
 trendCardCount: trendCards.length,
 trendGridColumns: gridStyle?.gridTemplateColumns,
 trendGridDisplay: gridStyle?.display,
 // Change 2: links
 providerLinkCount: providerLinks.length,
 links: providerLinks.map(a => ({
 href: a.href,
 target: a.target,
 rel: a.rel,
 text: a.innerText.trim(),
 }))
}, null, 2)"}

